var t=`1406-cassava-cake`;var n=`world-1406`;var s=`FJ`;var i=`oceania`;var o=8;var r=98;var c={en:`Cassava Cake`,ua:`Пиріг із маніоку`};var u={en:`Dense Fijian-style cassava and coconut cake. Cassava flour provides a practical pantry substitute for freshly grated cassava.`,ua:`Щільний фіджійський пиріг із маніоку та кокосу. Замість свіжого тертого маніоку використано маніокове борошно.`};var d=[{en:`Preheat oven to 180°C. Grease and line a 20 cm square pan; whisk cassava flour with baking powder and salt.`,ua:`Розігрійте духовку до 180°C. Змастіть та вистеліть пергаментом квадратну форму 20 см; змішайте маніокове борошно з розпушувачем і сіллю.`,t:[`mixing`],m:7,i:[[`cassava-flour`,290,`g`],[`baking-powder`,7,`g`],[`sea-salt`,3,`g`],[`coconut-oil`,12,`ml`]]},{en:`Stir coconut cream and brown sugar until dissolved; add desiccated coconut.`,ua:`Розмішайте кокосові вершки з коричневим цукром до розчинення й додайте кокосову стружку.`,t:[`mixing`],m:5,i:[[`coconut-cream`,340,`ml`],[`brown-sugar`,150,`g`],[`desiccated-coconut`,120,`g`]]},{en:`Mix wet and dry ingredients to a thick, spoonable batter; spread evenly into the prepared pan.`,ua:`Змішайте сухі та рідкі інгредієнти до густої маси, яку можна викладати ложкою; рівномірно розподіліть у формі.`,t:[`folding-batter`],m:6,i:[]},{en:`Bake 45–55 minutes at 180°C until golden and a skewer comes out without raw batter.`,ua:`Випікайте при 180°C 45–55 хвилин до золотистого кольору, доки шпажка не виходитиме без сирого тіста.`,t:[`baking`],m:50,i:[]},{en:`Let cool for 30 minutes before slicing; the crumb firms as it rests.`,ua:`Залиште охолоджуватися 30 хвилин перед нарізанням: м’якуш ущільниться під час вистигання.`,t:[`garnishing`],m:30,i:[]}];var l={slug:t,id:n,country:`FJ`,region:i,servings:8,minutes:98,title:c,text:u,steps:d};export{s as country,l as default,n as id,r as minutes,i as region,o as servings,t as slug,d as steps,u as text,c as title};